const fetchImage = async () => {
    try {
        const response = await fetch('http://host.docker.internal:3000/vercel.svg');
        if (!response.ok) {
            throw new Error(`Failed to fetch image: HTTP ${response.status}`);
        }
        const blob = await response.blob();
        const imageUrl = URL.createObjectURL(blob);
        const imageMetadata = new Image();
        imageMetadata.src = imageUrl;
        await new Promise(resolve => imageMetadata.onload = resolve);

        const svgContent = await response.text();
        const svgMetadata = extractSVGMetadata(svgContent);

        return {
            url: 'http://host.docker.internal:3000/vercel.svg',
            metadata: {
                image: imageMetadata,
                svg: svgMetadata
            }
        };
    } catch (error) {
        return { error: error.message };
    }
};

// Helper function to extract SVG metadata
const extractSVGMetadata = (svgContent) => {
    const metadataRegex = /<metadata[^>]*>([\s\S]*?)<\/metadata>/i;
    const match = svgContent.match(metadataRegex);

    if (match && match[1]) {
        return {
            type: 'SVG Metadata',
            content: match[1].trim()
        };
    }
    return { type: 'No SVG Metadata Found' };
};

fetchImage().catch(console.error);

const fetchSVG = async () => {
    const response = await fetch('http://host.docker.internal:3000/vercel.svg');
    if (!response.ok) {
        throw new Error(`Failed to fetch SVG: HTTP ${response.status}`);
    }
    const svgContent = await response.text();

    // Extract metadata from the SVG content
    const metadataRegex = /<metadata[^>]*>([\s\S]*?)<\/metadata>/i;
    const titleRegex = /<title[^>]*>([\s\S]*?)<\/title>/i;
    const descriptionRegex = /<desc[^>]*>([\s\S]*?)<\/desc>/i;
    const otherAttributesRegex = /<svg[^>]*(\s+[^>]*)/i;

    const metadata = {}
    const matches = svgContent.match(metadataRegex);
    if (matches && matches[1]) {
        metadata.metadata = matches[1].trim();
    }

    const titleMatch = svgContent.match(titleRegex);
    if (titleMatch && titleMatch[1]) {
        metadata.title = titleMatch[1].trim();
    }

    const descriptionMatch = svgContent.match(descriptionRegex);
    if (descriptionMatch && descriptionMatch[1]) {
        metadata.description = descriptionMatch[1].trim();
    }

    const otherAttributesMatch = svgContent.match(otherAttributesRegex);
    if (otherAttributesMatch && otherAttributesMatch[1]) {
        metadata.otherAttributes = otherAttributesMatch[1].trim();
    }

    return {
        url: 'http://host.docker.internal:3000/vercel.svg',
        metadata: metadata
    };
};

fetchSVG().catch(console.error);
